107	function StarRatingSmall({ rating }: { rating?: number | null }) {
108	  const t = useT();
109	  if (!rating) return <span className="text-[10px] text-muted-foreground italic">{t("detail.noReviews")}</span>;
110	  const full = Math.floor(rating);
111	  const hasHalf = rating - full >= 0.25 && rating - full < 0.75;
112	  const empty = 5 - full - (hasHalf ? 1 : 0);
113	  return (
114	    <div className="flex items-center gap-1">
115	      <div className="flex">
116	        {Array.from({ length: full }).map((_, i) => (
117	          <span key={`f${i}`} className="text-yellow-400 text-[11px] leading-none">★</span>
118	        ))}
119	        {hasHalf && <span className="text-yellow-300 text-[11px] leading-none">★</span>}
120	        {Array.from({ length: empty }).map((_, i) => (
121	          <span key={`e${i}`} className="text-muted-foreground/30 text-[11px] leading-none">★</span>
122	        ))}
123	      </div>
124	      <span className="text-xs font-semibold text-foreground">{rating.toFixed(1)}</span>
125	    </div>
126	  );
127	}
