129	function DragScrollRow({ children, className }: { children: React.ReactNode; className?: string }) {
130	  const ref = useRef<HTMLDivElement>(null);
131	  const dragging = useRef(false);
132	  const startX = useRef(0);
133	  const scrollLeft = useRef(0);
134	
135	  const scroll = (dir: "left" | "right") => {
136	    if (!ref.current) return;
137	    ref.current.scrollBy({ left: dir === "right" ? 320 : -320, behavior: "smooth" });
138	  };
139	
140	  return (
141	    <div className="relative group/carousel">
142	      {/* Left arrow only — no fade gradient */}
143	      <button
144	        type="button"
145	        onClick={() => scroll("left")}
146	        className="absolute left-2 top-1/2 -translate-y-1/2 z-20 w-9 h-9 rounded-full bg-background/90 border shadow-md flex items-center justify-center opacity-0 group-hover/carousel:opacity-100 transition-opacity hover:bg-accent"
147	        aria-label="Scroll left"
148	      >
149	        <ChevronLeft className="w-4 h-4" />
150	      </button>
151	
152	      <div
153	        ref={ref}
154	        className={`flex gap-4 overflow-x-auto snap-x snap-mandatory pb-3 cursor-grab active:cursor-grabbing select-none ${className ?? ""}`}
155	        style={{ scrollbarWidth: "none", msOverflowStyle: "none" } as React.CSSProperties}
156	        onMouseDown={(e) => {
157	          dragging.current = true;
158	          startX.current = e.pageX - (ref.current?.offsetLeft ?? 0);
159	          scrollLeft.current = ref.current?.scrollLeft ?? 0;
160	        }}
161	        onMouseMove={(e) => {
162	          if (!dragging.current || !ref.current) return;
163	          e.preventDefault();
164	          const x = e.pageX - ref.current.offsetLeft;
165	          ref.current.scrollLeft = scrollLeft.current - (x - startX.current) * 1.5;
166	        }}
167	        onMouseUp={() => { dragging.current = false; }}
168	        onMouseLeave={() => { dragging.current = false; }}
169	      >
170	        {children}
171	      </div>
172	
173	      {/* Right arrow only — no fade gradient */}
174	      <button
175	        type="button"
176	        onClick={() => scroll("right")}
177	        className="absolute right-2 top-1/2 -translate-y-1/2 z-20 w-9 h-9 rounded-full bg-background/90 border shadow-md flex items-center justify-center opacity-0 group-hover/carousel:opacity-100 transition-opacity hover:bg-accent"
178	        aria-label="Scroll right"
179	      >
180	        <ChevronRight className="w-4 h-4" />
181	      </button>
182	    </div>
183	  );
184	}
