221	          <SportIcon sport={court.type} size={40} style={{ color }} />
222	        </div>
223	      )}
224	
225	      <CardHeader className="pb-2">
226	        <div className="flex justify-between items-start mb-2 gap-2">
227	          <div className="flex gap-1.5 flex-wrap items-center">
228	            <SportPill
229	              sport={court.type}
230	              variant={hovered ? "solid" : "subtle"}
231	              className="transition-all duration-200"
