247	          style={{ color: hovered ? color : undefined }}
248	        >
249	          {court.name}
250	        </CardTitle>
251	        <CardDescription className="flex items-center text-xs">
252	          <MapPin className="h-3 w-3 mr-1 shrink-0" />
253	          <span className="truncate">{court.city}{court.address ? ` — ${court.address}` : ""}</span>
254	        </CardDescription>
255	      </CardHeader>
256	
257	      <CardFooter className="pt-0 mt-auto gap-2">
258	        <Link href={`/courts/${court.id}`} aria-label={t("card.view")}>
259	          <Button
260	            variant="outline"
261	            size="icon"
262	            className="shrink-0 transition-all duration-200 active:scale-[0.98]"
263	            title={t("card.view")}
264	          >
265	            <Eye className="w-4 h-4" />
266	          </Button>
267	        </Link>
268	        <Link href={`/courts/${court.id}#reserve`} className="flex-1"
269	          onMouseEnter={() => setBtnHovered(true)}
270	          onMouseLeave={() => setBtnHovered(false)}
271	        >
272	          <Button
273	            className="w-full transition-all duration-200 active:scale-[0.98] font-semibold"
274	            style={{ backgroundColor: color, borderColor: color, color: "#fff", ...(btnHovered ? { boxShadow: `0 4px 14px ${color}55` } : {}) }}
275	          >
276	            {t("card.reserve")}
277	          </Button>
278	        </Link>
279	      </CardFooter>
280	    </Card>
281	  );
