284	export default function Home() {
285	  const t = useT();
286	  const isMobile = useIsMobile();
287	  const { isSignedIn } = useUser();
288	  const queryClient = useQueryClient();
289	  const { favorites, loading: favLoading } = useFavoritesContext();
290	  const [heroIdx, setHeroIdx] = useState(0);
291	  const ALL_SPORTS = Object.keys(sportLithuanian);
292	  const [activeSports, setActiveSports] = useState<Set<string>>(new Set(ALL_SPORTS));
293	
294	  const toggleSport = (sport: string) => {
295	    setActiveSports(prev => {
296	      const next = new Set(prev);
297	      if (next.has(sport)) { next.delete(sport); } else { next.add(sport); }
298	      return next;
299	    });
300	  };
301	  const allActive = activeSports.size === ALL_SPORTS.length;
302	  const [hoveredStat, setHoveredStat] = useState<string | null>(null);
303	  const [tappedStat, setTappedStat] = useState<string | null>(null);
304	
305	  // Search bar state
306	  const [, setLocation] = useLocation();
307	  const [searchName, setSearchName] = useState("");
308	  const [searchSport, setSearchSport] = useState("");
309	  const [searchCity, setSearchCity] = useState("");
310	  const [searchDate, setSearchDate] = useState("");
311	  const [searchTime, setSearchTime] = useState("");
312	  const [dropdownOpen, setDropdownOpen] = useState(false);
313	  const searchRef = useRef<HTMLDivElement>(null);
314	  const [cityDropdownOpen, setCityDropdownOpen] = useState(false);
315	  const [cityInput, setCityInput] = useState("");
316	  const cityRef = useRef<HTMLDivElement>(null);
317	  const [timeDropdownOpen, setTimeDropdownOpen] = useState(false);
318	  const [timeSlider, setTimeSlider] = useState<number | null>(null);
319	  const timeRef = useRef<HTMLDivElement>(null);
320	  const [dateDropdownOpen, setDateDropdownOpen] = useState(false);
321	  const [searchDateObj, setSearchDateObj] = useState<Date | undefined>(undefined);
322	  const dateRef = useRef<HTMLDivElement>(null);
323	  const [showMoreCities, setShowMoreCities] = useState(false);
324	  const { locale } = useI18n();
325	
326	  // Time-of-day accent — uses local browser time so it's already location-aware
327	  const [currentHour, setCurrentHour] = useState(() => new Date().getHours());
328	  useEffect(() => {
329	    const tick = setInterval(() => setCurrentHour(new Date().getHours()), 60_000);
330	    return () => clearInterval(tick);
331	  }, []);
332	
333	  const TIME_PALETTES: { label: string; color: string; fg: string }[] = [
334	    { label: "dawn",      color: "#38bdf8", fg: "#000" }, // 05-09  sky blue
335	    { label: "morning",   color: "#84cc16", fg: "#000" }, // 10-13  lime (default)
336	    { label: "afternoon", color: "#f59e0b", fg: "#000" }, // 14-16  warm amber
337	    { label: "evening",   color: "#f97316", fg: "#000" }, // 17-20  sunset orange
338	    { label: "night",     color: "#8b5cf6", fg: "#fff" }, // 21-04  indigo/night
339	  ];
340	  const timePalette =
341	    currentHour >= 5  && currentHour < 10 ? TIME_PALETTES[0] :
342	    currentHour >= 10 && currentHour < 14 ? TIME_PALETTES[1] :
343	    currentHour >= 14 && currentHour < 17 ? TIME_PALETTES[2] :
344	    currentHour >= 17 && currentHour < 21 ? TIME_PALETTES[3] :
345	    TIME_PALETTES[4];
346	
347	  const timeAccent = timePalette.color;
348	
349	  const accentColor = searchSport ? (sportColor[searchSport] ?? timeAccent) : timeAccent;
350	  function contrastText(hex: string) {
351	    const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
352	    return (0.299*r + 0.587*g + 0.114*b) / 255 > 0.55 ? "#000" : "#fff";
353	  }
354	  const accentFg = contrastText(accentColor);
355	
356	  function handleSearch() {
357	    const params = new URLSearchParams();
358	    if (searchName.trim()) params.set("name", searchName.trim());
359	    if (searchSport) params.set("type", searchSport);
360	    if (searchCity) params.set("city", searchCity);
361	    if (searchDate) params.set("date", searchDate);
362	    if (searchTime) params.set("time", searchTime);
363	    setLocation(`/courts${params.toString() ? "?" + params.toString() : ""}`);
364	  }
365	
366	  useEffect(() => {
367	    function handleClick(e: MouseEvent) {
368	      if (searchRef.current && !searchRef.current.contains(e.target as Node)) {
369	        setDropdownOpen(false);
370	      }
371	      if (cityRef.current && !cityRef.current.contains(e.target as Node)) {
372	        setCityDropdownOpen(false);
373	      }
374	      if (timeRef.current && !timeRef.current.contains(e.target as Node)) {
375	        setTimeDropdownOpen(false);
376	      }
377	      if (dateRef.current && !dateRef.current.contains(e.target as Node)) {
378	        setDateDropdownOpen(false);
379	      }
380	    }
381	    document.addEventListener("mousedown", handleClick);
382	    return () => document.removeEventListener("mousedown", handleClick);
383	  }, []);
384	
385	  useEffect(() => {
386	    const interval = setInterval(() => {
387	      setHeroIdx((i) => (i + 1) % HERO_IMAGES.length);
388	    }, 5000);
389	    return () => clearInterval(interval);
390	  }, []);
391	
392	  useEffect(() => {
393	    queryClient.invalidateQueries({ queryKey: ["courts"] });
394	    queryClient.invalidateQueries({ queryKey: ["cities"] });
395	  }, [queryClient]);
396	
397	  const base = import.meta.env.BASE_URL.replace(/\/$/, "");
398	
399	  const { data: stats, isLoading: statsLoading } = useGetStatsSummary({
400	    query: { queryKey: getGetStatsSummaryQueryKey(), refetchOnMount: "always", refetchOnWindowFocus: true, staleTime: 0 },
401	  });
402	  const { data: popularCourts, isLoading: popularLoading } = useGetPopularCourts({
403	    query: { queryKey: getGetPopularCourtsQueryKey(), refetchOnMount: "always", refetchOnWindowFocus: true, staleTime: 0 },
404	  });
405	  const { data: courts, isLoading: courtsLoading } = useListCourts(undefined, {
406	    query: { queryKey: getListCourtsQueryKey(), refetchOnMount: "always", refetchOnWindowFocus: true, staleTime: 0 },
407	  });
408	
409	  const filteredCourts = searchName.trim().length >= 2
410	    ? (courts ?? [])
411	        .filter(c => c.name.toLowerCase().includes(searchName.trim().toLowerCase()))
412	        .slice(0, 7)
413	    : [];
414	
415	  const uniqueCities = [...new Set((courts ?? []).map(c => c.city).filter((c): c is string => !!c))].sort();
416	
417	  // City combobox helpers
418	  const cityCounts = (courts ?? []).reduce<Record<string, number>>((acc, c) => {
419	    if (c.city) acc[c.city] = (acc[c.city] ?? 0) + 1;
420	    return acc;
421	  }, {});
422	  const TOP_N = 5;
423	  const popularCities = [...uniqueCities].sort((a, b) => (cityCounts[b] ?? 0) - (cityCounts[a] ?? 0)).slice(0, TOP_N);
424	  const otherCities = uniqueCities.filter(c => !popularCities.includes(c));
425	  const cityFilter = cityInput.trim().toLowerCase();
426	  const filteredPopular = popularCities.filter(c => !cityFilter || c.toLowerCase().includes(cityFilter));
427	  const filteredOther = otherCities.filter(c => !cityFilter || c.toLowerCase().includes(cityFilter));
428	
429	  const heroLines = t("home.hero.title").split("\n");
430	
431	  return (
432	    <Layout>
433	      {/* Hero Section — split layout */}
434	      <section className="bg-background text-foreground">
435	        <div className="flex lg:pl-[max(0px,calc((100vw-64rem)/2))] xl:pl-[max(0px,calc((100vw-80rem)/2))] 2xl:pl-[max(0px,calc((100vw-96rem)/2))]">
436	
437	          {/* ── LEFT PANEL: search form ── */}
438	          <div className="relative z-10 w-full md:w-[400px] lg:w-[440px] xl:w-[480px] flex-shrink-0 flex flex-col justify-start px-5 sm:px-6 lg:pl-4 lg:pr-10 pt-6 pb-6 lg:pt-12 lg:pb-14">
439	            {/* subtle top-left glow */}
440	            <div className="absolute inset-0 pointer-events-none opacity-20 bg-[radial-gradient(ellipse_at_top_left,_var(--tw-gradient-stops))] from-primary/50 via-transparent to-transparent" />
441	            
442	            {/* Multi-row search widget */}
443	              <div className="w-full space-y-2.5 sm:space-y-2" ref={searchRef}>
444	
