116	/**
117	 * Build a marker icon that matches the filter legend exactly:
118	 * colored circle + white sport icon centered at the natural (12,12) origin,
119	 * same strokeWidth=2 as the SportIcon components in the filter.
120	 */
121	function buildIconUrl(color: string, sport: string, isSelected: boolean): string {
122	  const size = isSelected ? 44 : 34;
123	  const border = isSelected ? 3 : 2;
124	  const cx = size / 2;
125	  const cy = size / 2;
126	  const r = size / 2 - border / 2;
127	
128	  const iconPx = size * 0.58;
129	  const iconScale = iconPx / 24;
130	  const tx = (cx - 12 * iconScale).toFixed(3);
131	  const ty = (cy - 12 * iconScale).toFixed(3);
132	  const sw = (2 / iconScale).toFixed(2);
133	
134	  const paths = sportIconPaths[sport] ?? sportIconPaths["tennis"];
135	
136	  // Plain circle — no filter/shadow so there is zero gray bleed outside the circle
137	  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
138	  <circle cx="${cx}" cy="${cy}" r="${r}" fill="${color}" stroke="white" stroke-width="${border}"/>
139	  <g transform="translate(${tx},${ty}) scale(${iconScale.toFixed(4)})" fill="none" stroke="white" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round">${paths}</g>
140	</svg>`;
141	
142	  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
143	}
144	
145	/** Pre-compute all icon variants once — 6 sports × 2 states = 12 icons */
146	function buildIconCache(): Record<string, { normal: google.maps.Icon; selected: google.maps.Icon }> {
147	  const cache: Record<string, { normal: google.maps.Icon; selected: google.maps.Icon }> = {};
148	  for (const [sport, color] of Object.entries(SPORT_COLOR)) {
149	    cache[sport] = {
150	      normal: {
151	        url: buildIconUrl(color, sport, false),
152	        scaledSize: new google.maps.Size(34, 34),
153	        anchor: new google.maps.Point(17, 17),
154	      },
155	      selected: {
156	        url: buildIconUrl(color, sport, true),
157	        scaledSize: new google.maps.Size(44, 44),
158	        anchor: new google.maps.Point(22, 22),
159	      },
160	    };
161	  }
162	  return cache;
163	}
