425	/** Haversine distance in km between two lat/lng points */
426	function haversineKm(lat1: number, lng1: number, lat2: number, lng2: number): number {
427	  const R = 6371;
428	  const dLat = ((lat2 - lat1) * Math.PI) / 180;
429	  const dLng = ((lng2 - lng1) * Math.PI) / 180;
430	  const a =
431	    Math.sin(dLat / 2) ** 2 +
432	    Math.cos((lat1 * Math.PI) / 180) * Math.cos((lat2 * Math.PI) / 180) * Math.sin(dLng / 2) ** 2;
433	  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
434	}
