125	/** Format total minutes → "HH:MM" */
126	function minToTime(mins: number): string {
127	  const h = Math.floor(mins / 60);
128	  const m = mins % 60;
129	  return `${h.toString().padStart(2, "0")}:${m.toString().padStart(2, "0")}`;
130	}
